export const CUES = [{"t": 2.2, "end": 9.94, "lines": [{"t0": 2.2, "t1": 6.89, "text": "For millions of years, our ancestors lived as other animals do:"}, {"t0": 6.89, "t1": 10.54, "text": "when the sun went down, the day was over."}]}, {"t": 12.6, "end": 16.32, "lines": [{"t0": 12.6, "t1": 16.92, "text": "Then someone, somewhere, learned to keep a fire alive."}]}, {"t": 29.6, "end": 40.27, "lines": [{"t0": 29.6, "t1": 32.4, "text": "No one knows who, or when."}, {"t0": 32.26, "t1": 37.11, "text": "Burnt bone in a South African cave hints at fire a million years ago,"}, {"t0": 37.11, "t1": 40.87, "text": "though everyday use may have come much later."}]}, {"t": 47.6, "end": 52.23, "lines": [{"t0": 47.6, "t1": 49.71, "text": "Either way, for the first time,"}, {"t0": 49.71, "t1": 52.83, "text": "the day did not end when the sun did."}]}, {"t": 56.0, "end": 62.92, "lines": [{"t0": 56.0, "t1": 59.88, "text": "The oldest fossils of our own species, found in Morocco,"}, {"t0": 59.88, "t1": 63.52, "text": "are around three hundred thousand years old."}]}, {"t": 64.4, "end": 75.3, "lines": [{"t0": 64.4, "t1": 71.79, "text": "From Africa, people spread across the world: by sea to Australia at least fifty thousand years ago,"}, {"t0": 71.79, "t1": 75.9, "text": "and into the Americas before the Ice Age ended."}]}, {"t": 78.4, "end": 88.97, "lines": [{"t0": 78.4, "t1": 80.5, "text": "On a cave wall in Indonesia,"}, {"t0": 80.5, "t1": 86.72, "text": "someone left the outline of a hand at least sixty-seven thousand years ago."}, {"t0": 86.58, "t1": 89.57, "text": "It is the oldest cave art we know."}]}, {"t": 92.6, "end": 100.05, "lines": [{"t0": 92.6, "t1": 95.55, "text": "Starting around eleven thousand years ago,"}, {"t0": 95.55, "t1": 100.65, "text": "in several parts of the world, separately, people began to farm."}]}, {"t": 101.6, "end": 114.01, "lines": [{"t0": 101.6, "t1": 104.78, "text": "Wheat and barley in the Middle East."}, {"t0": 104.64, "t1": 107.54, "text": "Rice and millet in China."}, {"t0": 107.4, "t1": 109.8, "text": "Maize in Mexico."}, {"t0": 109.66, "t1": 112.42, "text": "Potatoes in the Andes."}, {"t0": 112.28, "t1": 114.61, "text": "Sorghum in Africa."}]}, {"t": 115.4, "end": 120.74, "lines": [{"t0": 115.4, "t1": 117.46, "text": "It was hard work."}, {"t0": 117.32, "t1": 121.34, "text": "But a field can feed far more people than a forest."}]}, {"t": 122.6, "end": 126.55, "lines": [{"t0": 122.6, "t1": 127.15, "text": "Villages became towns, and towns became cities."}]}, {"t": 127.4, "end": 134.27, "lines": [{"t0": 127.4, "t1": 131.25, "text": "Five thousand years ago, Uruk, in what is now Iraq,"}, {"t0": 131.25, "t1": 134.87, "text": "was home to tens of thousands of people."}]}, {"t": 137.0, "end": 139.31, "lines": [{"t0": 137.0, "t1": 139.91, "text": "And here, people began to write."}]}, {"t": 145.0, "end": 151.8, "lines": [{"t0": 145.0, "t1": 148.11, "text": "The first writing wasn't poetry."}, {"t0": 147.97, "t1": 152.4, "text": "It was accounts: barley, beer, sheep, and who owed what."}]}, {"t": 152.8, "end": 160.27, "lines": [{"t0": 152.8, "t1": 156.21, "text": "Writing was invented at least three times,"}, {"t0": 156.21, "t1": 160.87, "text": "independently: here, in China, and in Mesoamerica."}]}, {"t": 161.6, "end": 166.98, "lines": [{"t0": 161.6, "t1": 165.69, "text": "At about the same time, someone made the first wheel."}, {"t0": 165.55, "t1": 167.58, "text": "We don't know who."}]}, {"t": 170.6, "end": 178.74, "lines": [{"t0": 170.6, "t1": 176.44, "text": "Empires rose and fell, and roads and sea lanes carried silk and spices,"}, {"t0": 176.44, "t1": 179.34, "text": "horses and glass, and ideas."}]}, {"t": 179.4, "end": 191.69, "lines": [{"t0": 179.4, "t1": 183.07, "text": "Buddhism travelled from India to China."}, {"t0": 182.93, "t1": 186.27, "text": "Paper went from China to Baghdad."}, {"t0": 186.13, "t1": 189.22, "text": "And the numerals we still use, born in India,"}, {"t0": 189.22, "t1": 192.29, "text": "reached Europe through Arabic books."}]}, {"t": 194.6, "end": 204.6, "lines": [{"t0": 194.6, "t1": 196.33, "text": "Far out in the Pacific,"}, {"t0": 196.33, "t1": 205.2, "text": "navigators reading the stars and the swell found and settled almost every island in the widest ocean on Earth."}]}, {"t": 207.6, "end": 219.65, "lines": [{"t0": 207.6, "t1": 212.91, "text": "Printing began in China, and movable type in China and Korea."}, {"t0": 212.77, "t1": 214.75, "text": "In Europe, around 1450,"}, {"t0": 214.75, "t1": 220.25, "text": "Gutenberg's press met an alphabet of a few dozen letters."}]}, {"t": 221.0, "end": 224.65, "lines": [{"t0": 221.0, "t1": 223.1, "text": "Books multiplied."}, {"t0": 222.96, "t1": 225.25, "text": "So did arguments."}]}, {"t": 226.4, "end": 233.36, "lines": [{"t0": 226.4, "t1": 230.22, "text": "In 1492, European ships reached the Americas,"}, {"t0": 230.22, "t1": 233.96, "text": "and two halves of the world collided."}]}, {"t": 234.6, "end": 249.48, "lines": [{"t0": 234.6, "t1": 239.06, "text": "Maize and potatoes went on to feed much of the world."}, {"t0": 238.92, "t1": 244.23, "text": "But diseases from Europe killed a large share of the people of the Americas,"}, {"t0": 244.23, "t1": 250.08, "text": "and over twelve million Africans were forced across the Atlantic in chains."}]}, {"t": 252.4, "end": 258.96, "lines": [{"t0": 252.4, "t1": 256.4, "text": "In 1610, Galileo turned a telescope on Jupiter,"}, {"t0": 256.4, "t1": 259.56, "text": "and saw moons going around it."}]}, {"t": 260.4, "end": 265.91, "lines": [{"t0": 260.4, "t1": 263.23, "text": "Science was a new habit: look carefully,"}, {"t0": 263.23, "t1": 266.51, "text": "test the idea, and trust the evidence."}]}, {"t": 268.6, "end": 275.25, "lines": [{"t0": 268.6, "t1": 271.64, "text": "Then steam engines turned coal into motion,"}, {"t0": 271.64, "t1": 275.85, "text": "and factories and railways spread across the world."}]}, {"t": 276.6, "end": 290.1, "lines": [{"t0": 276.6, "t1": 281.54, "text": "With them, and with medicine, ordinary lives began to change."}, {"t0": 281.4, "t1": 282.04, "text": "In 1800,"}, {"t0": 282.04, "t1": 287.42, "text": "more than four in ten children died before the age of five."}, {"t0": 287.28, "t1": 290.7, "text": "Today, fewer than one in twenty do."}]}, {"t": 294.6, "end": 296.54, "lines": [{"t0": 294.6, "t1": 297.14, "text": "And then, the night changed."}]}, {"t": 308.2, "end": 315.2, "lines": [{"t0": 308.2, "t1": 310.1, "text": "Electricity."}, {"t0": 309.96, "t1": 312.1, "text": "Light at the flick of a switch,"}, {"t0": 312.1, "t1": 315.8, "text": "and power carried by wire to almost anywhere."}]}, {"t": 318.0, "end": 326.4, "lines": [{"t0": 318.0, "t1": 323.0, "text": "In 1903, a powered aeroplane flew for twelve seconds."}, {"t0": 322.86, "t1": 327.0, "text": "Sixty-six years later, people walked on the Moon."}]}, {"t": 329.0, "end": 336.54, "lines": [{"t0": 329.0, "t1": 334.27, "text": "Today, most of the eight billion people alive carry a computer in their pocket,"}, {"t0": 334.27, "t1": 337.14, "text": "connected to nearly everyone else."}]}, {"t": 342.0, "end": 344.45, "lines": [{"t0": 342.0, "t1": 345.05, "text": "And that is everything, so far."}]}, {"t": 349.6, "end": 354.31, "lines": [{"t0": 349.6, "t1": 352.57, "text": "Ahead, the cardboard is still blank."}, {"t0": 352.43, "t1": 354.91, "text": "No one has cut it yet."}]}, {"t": 357.8, "end": 359.5, "lines": [{"t0": 357.8, "t1": 360.1, "text": "That part is up to us."}]}];
